// Источник: web-тест .qa/e2e/tests/nusach-switch/ns-02-profile-unchanged.spec.ts, план .qa/e2e/specs/nusach-switch.md, кейс .qa/tests/nusach-switch/NS-02-switch-keeps-position.md
// Тикет #6a86f7d8 «פיתוח: החלפת נוסח בתוך התפילה». Опора: F-37 AC2, AC3 · S-33 AC3 (смена в молитве не меняет профиль).
import { expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, byLabel, byLabelStartsWith, tapText, tapLabel, expectVisibleText, scrollToText } from '../../helpers/ui.ts';
import { openPrayer, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const PRAYERS: Record<string, string> = { 'שחרית': 'shacharit', 'מנחה': 'mincha', 'ערבית': 'arvit' };
const NUSACH: Record<string, string> = { 'אשכנז': 'ashkenaz', 'ספרד': 'sfarad' };

/**
 * «התחל תפילה» на главной (как web-хелпер _helpers/prayer-start.ts, решение 2026-10-04):
 * кнопка активна — нажать; неактивна вне окна молитвы — рядом «<תפילה> מתחילה ב-HH:MM» (норма),
 * тогда открыть ту же молитву из «תפילות» (нусах карточки = нусах профиля).
 */
async function startNearestPrayer() {
  const start = await byLabel('התחל תפילה');
  await start.waitForDisplayed({ timeout: 20000 });
  if (await start.isEnabled()) { await start.click(); return; }
  const startsAt = await byTextMatches('.*מתחילה ב-?\\s?\\d{1,2}:\\d{2}.*');
  await expect(startsAt).toBeDisplayed();
  const line = await startsAt.getText();
  const prayer = Object.keys(PRAYERS).find((p) => line.includes(p));
  const nusachLine = await (await byTextMatches('.*נוסח (אשכנז|ספרד).*')).getText();
  const nusach = nusachLine.match(/נוסח (אשכנז|ספרד)/)?.[1];
  expect(prayer).toBeTruthy();
  expect(nusach).toBeTruthy();
  await openPrayer(`${PRAYERS[prayer!]}_${NUSACH[nusach!]}`, prayer!);
}

describe('Смена нусаха внутри молитвы', () => {
  afterEach(async () => { await toHome(); });

  it('NS-02 После смены нусаха в молитве профиль не меняется #6a86f7d8 @prod-safe', async () => {
    // 1. מנחה (אשכנזי), «1 מתוך 8».
    await openPrayer('mincha_ashkenaz', 'מנחה');
    await goToPage(1, 8);

    // 2. Меню нусаха → «ספרדי» → «החלף» → «מנחה (ספרדי)».
    await (await byLabelStartsWith('בחירת נוסח')).click();
    await tapText('ספרדי');
    await tapText('החלף');
    await expectVisibleText('מנחה (ספרדי)');

    // 3. Профиль: «נוסח תפילה» = אשכנז (не ספרד).
    await toHome();
    await tapLabel('מעבר לפרטים שלי');
    await scrollToText('נוסח תפילה');
    await expectVisibleText('נוסח תפילה');
    await expectVisibleText('אשכנז');
    await expect(byText('ספרד')).not.toBeDisplayed();

    // 4. Главная → «התחל תפילה» — молитва открывается в נוסח профиля (אשכנזי).
    await toHome();
    await startNearestPrayer();
    await expect(byTextContains('(אשכנזי)')).toBeDisplayed();

    // Вернуть מנחה в אשכנזי, если приложение запомнило выбор в самой молитве (не влиять на другие тесты).
    await toHome();
    await openPrayer('mincha_ashkenaz', 'מנחה');
    if (await (await byText('מנחה (ספרדי)')).isDisplayed().catch(() => false)) {
      await (await byLabelStartsWith('בחירת נוסח')).click();
      await tapText('אשכנזי');
      const replace = await byText('החלף');
      if (await replace.isDisplayed().catch(() => false)) await replace.click();
    }
    await expectVisibleText('מנחה (אשכנזי)');
  });
});
